{
  "tasks": [
    {
      "task_id": "T01",
      "title": "已完成任务工时总和按项目汇总（排除丙）",
      "business_question": "统计状态为“已完成”且项目不为“丙”的任务，其工时字段的总和是多少？请按项目分组展示。",
      "priority": "P0",
      "priority_reason": "直接回答核心分析目标：已完成任务的工时总和按项目汇总并排除特定项目。删除此任务将无法获得任何关于工时分布或总量的有效结论。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              },
              {
                "field": "field_0002",
                "operator": "ne",
                "value": "丙"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    }
  ]
}
